/**
 * Библиотека условных знаков: логические категории, описание каждого элемента,
 * варианты оформления по стилям, учёт принадлежности и ссылки на первоисточники.
 *
 * Уставные знаки — система РККА 1942–1945 по TM 30-430 «Handbook on U.S.S.R.
 * Military Forces», гл. XII «Conventional signs» (War Department, 1946), где
 * воспроизведены таблицы советских тактических знаков военного времени.
 * Остальные варианты оформления — не системы знаков, а манера исторических карт,
 * воспроизведённая по образцам (атлас, инфографика, схема боя).
 *
 * Пометка verify ставится только там, где начертание не подтверждено 
 * первоисточником (знак построен по аналогии или по практике атласов).
 */
import type { FeatureKind } from './model';

export type StyleId = 'rkka' | 'atlas' | 'inf' | 'tac';

/**
 * Варианты оформления знаков. Это НЕ разные системы условных знаков: смысл знака
 * (элемент библиотеки) один, меняется только его начертание.
 *  — standard: начертание по нормативной таблице знаков (первоисточник);
 *  — sample: манера оформления, воспроизведённая по образцу карты.
 */
export interface StyleInfo {
  id: StyleId;
  name: string;
  short: string;
  /** standard — по нормативной таблице знаков; sample — манера, воспроизведённая по образцу карты. */
  basis: 'standard' | 'sample';
  description: string;
  /** Откуда взято начертание: первоисточник или образец. */
  origin: string;
  /** Что именно воспроизводится — характерные приёмы оформления. */
  traits: string[];
  /** Для каких карт подходит. */
  use: string;
}

