/** Первоисточники. В элементах ссылка пишется «ключ:страница». */
export const SOURCES: { id: string; short: string; title: string; pages: string }[] = [
  { id: 'tm', short: 'TM 30-430', title: 'TM 30-430. Handbook on U.S.S.R. Military Forces. Chapter XII: Conventional Signs and Military Symbols. War Department, 1946 (таблицы знаков РККА 1942–1945)', pages: 'с.' },
];

/** Ссылки элемента в читаемом виде: «TM 30-430, с. XII-7; TM 30-430, с. XII-14». */
export function sourceText(refs: string[] | undefined): string {
  return (refs ?? []).map((r) => {
    const [id, page] = r.split(':');
    const s = SOURCES.find((x) => x.id === id);
    return s ? `${s.short}${page ? `, ${s.pages} ${page}` : ''}` : r;
  }).join('; ');
}

